def single_number(nums):
    for i in range(len(nums)):
        count = 0
        for num in nums:                                        # rescans the whole array for every element
            if num == nums[i]:
                count += 1
        if count == 1:
            return nums[i]
    return -1


if __name__ == "__main__":
    nums = [4, 1, 2, 1, 2]
    print(single_number(nums))

